// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address attacker, address fakeLog) public {
        vm.assume(attacker != address(0));
        vm.assume(fakeLog != address(0));
        vm.startPrank(attacker);
        c.Initialized();
        bool ok;
        try c.SetLogFile(fakeLog) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        // Rule: once Initialized() has been called, any SetLogFile call must revert,
        // so LogFile can never be replaced after initialization.
        assertTrue(!ok, "SetLogFile must revert after initialization");
    }
}
